        open(f'/app/data/files/{fid}','wb').write(data);return c.execute('SELECT * FROM files WHERE id=?',(fid,)).fetchone()
def file_to_json(r):return {k:r[k] for k in ('id','uploader_id','filename','content_type','size','created_at')}
