    d=await read_json(r)
    if not isinstance(d,dict) or not isinstance(d.get('username'),str) or not isinstance(d.get('password'),str) or not __import__('re').fullmatch(r'[A-Za-z0-9_]+',d['username']) or len(d['password'])<8:return err(400,'invalid')
